--
-- Archaeology (world): consolidated, idempotent final state.
-- Merged from agatho/TrinityCore feature/archaeology world updates
--   2026_08_15_00..12_world_archaeology.sql (13 files) into one pass:
--   dig sites (EK/Kalimdor + Outland/Northrend + Pandaria), their boundary
--   polygons, research-branch policy, find GameObject wiring + loot, and the
--   Survey/Solve spell-script bindings.
--
-- PROVENANCE (evry/master-track/archaeology, via the agatho port):
--   * dig-site -> branch mapping and polygons: Archy addon dig-site DB /
--     QuestPOIPoint joined through ResearchSite.QuestPOIBlobID - server-owned
--     reference data the client DB2 does not carry. Content stops at Pandaria
--     (map 870); there is no Draenor+ data and none was invented.
--   * PROVISIONAL-FROM-FORK: findCount = 6 everywhere; polygons are 12
--     vertices rounded to whole world units; 5-9 fragments per find; 7%
--     keystone chance (see the fuse note in the loot section).
-- Safe to re-run: every section clears only the rows it re-inserts.
--

-- ============================================================================
-- 1. Dig sites: research site -> branch + finds required to exhaust it.
-- ============================================================================
CREATE TABLE IF NOT EXISTS `archaeology_dig_site` (
  `researchSiteId` int unsigned NOT NULL DEFAULT '0' COMMENT 'ResearchSite.db2 ID',
  `researchBranchId` int unsigned NOT NULL DEFAULT '0' COMMENT 'ResearchBranch.db2 ID',
  `findCount` tinyint unsigned NOT NULL DEFAULT '6' COMMENT 'finds required to exhaust the site',
  PRIMARY KEY (`researchSiteId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Archaeology dig site to research branch (fork reference data)';
DELETE FROM `archaeology_dig_site`;

-- ============================================================================
-- 2. Dig-site boundary polygons (world X/Y), 12 vertices per site.
-- ============================================================================
CREATE TABLE IF NOT EXISTS `archaeology_dig_site_point` (
  `researchSiteId` int unsigned NOT NULL DEFAULT '0' COMMENT 'ResearchSite.db2 ID',
  `idx` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'polygon vertex order',
  `posX` float NOT NULL DEFAULT '0',
  `posY` float NOT NULL DEFAULT '0',
  PRIMARY KEY (`researchSiteId`,`idx`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Archaeology dig site boundary polygons (world coords)';
DELETE FROM `archaeology_dig_site_point`;

-- ============================================================================
-- 3. Research branches: branch find GameObject per race. Fragment
--    currencies come from ResearchBranch.db2 CurrencyID; keystone identity
--    from ItemID. Fossil (3) has ItemID 0 -> no keystone. Pandaria branches
--    (29/229/231) ship without provisional keystone rows.
-- ============================================================================
CREATE TABLE IF NOT EXISTS `archaeology_research_branch` (
  `researchBranchId` smallint unsigned NOT NULL COMMENT 'ResearchBranch.db2 ID',
  `findGameObjectId` int unsigned NOT NULL COMMENT 'Branch-specific archaeology find GameObject',
  PRIMARY KEY (`researchBranchId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Archaeology server-owned branch policy';
DELETE FROM `archaeology_research_branch` WHERE `researchBranchId` IN (1,2,3,4,5,6,7,8,27,29,229,231);

-- ============================================================================
-- 4. Find GameObjects: script + loot-template id (data1) for every branch
--    find. Find objects are retail chests with lock 1859.
-- ============================================================================
UPDATE `gameobject_template`
SET `ScriptName` = 'go_archaeology_find',
    `data1` = CASE `entry`
      WHEN 202655 THEN 35546 -- Troll
      WHEN 203071 THEN 35827 -- Night Elf
      WHEN 203078 THEN 36055 -- Nerubian
      WHEN 204282 THEN 28434 -- Dwarf
      WHEN 206836 THEN 35733 -- Fossil
      WHEN 207187 THEN 36019 -- Orc
      WHEN 207188 THEN 36037 -- Draenei
      WHEN 207189 THEN 36054 -- Vrykul
      WHEN 207190 THEN 36056 -- Tol'vir
      WHEN 211163 THEN 41486 -- Pandaren
      WHEN 211174 THEN 41505 -- Mogu
      WHEN 218950 THEN 46918 -- Mantid
    END
WHERE `entry` IN (202655,203071,203078,204282,206836,207187,207188,207189,207190,211163,211174,218950);

-- ============================================================================
-- 5. Find loot: fragments (ItemType 2, 100%, 5-9 per find) + provisional
--    keystones (ItemType 0, 7%, quantity 1). The Cataclysm six loot entries
--    are fully owned by this file (wiped entirely); the later branches keep
--    the filtered deletes from their source migrations.
--
--    One-line fuse once an authoritative keystone rate exists:
--      UPDATE `gameobject_loot_template` SET `Chance` = <retail>
--      WHERE `Comment` LIKE '%provisional keystone%';
-- ============================================================================
DELETE FROM `gameobject_loot_template`
WHERE `Entry` IN (28434,35546,35733,35827,36055,36056)
   OR (`Entry` IN (36019,36037,36054,41486,41505,46918) AND `ItemType` = 2
       AND `Item` IN (397,398,399,676,677,754))
   OR (`Entry` IN (36019,36037,36054) AND `ItemType` = 0
       AND `Item` IN (52843,63127,63128,64392,64394,64395,64396,64397));

-- ============================================================================
-- 6. Spell scripts: Survey (80451) and every research project's solve
--    spell. Solving = casting the project's own SpellID
--    (ResearchProject.db2); the script adds the fragment/keystone spend,
--    completion history and the next-project roll.
-- ============================================================================

DELETE FROM `spell_script_names` WHERE `ScriptName` = 'spell_archaeology_survey';

DELETE FROM spell_script_names WHERE ScriptName = 'spell_archaeology_solve';
